const crypto = require('crypto');
const body = $json.body ?? $json;
const headers = $json.headers ?? {};
const tokenHeader = headers['x-govhub-token'] || headers['X-GOVHUB-TOKEN'];
const allowed = String($env.GOVHUB_TOKENS || '').split(',').map((v) => v.trim()).filter(Boolean);
if (!tokenHeader || !allowed.includes(String(tokenHeader).trim())) {
  return [{ json: { ok: false, statusCode: 401, error_code: 'AUTH_INVALID_TOKEN', message: 'invalid token' } }];
}
const required = ['mission_key', 'repo_key', 'agent_id', 'branch', 'head_sha', 'report_md'];
for (const k of required) {
  if (!body[k]) {
    return [{ json: { ok: false, statusCode: 400, error_code: 'REPORT_INGEST_INVALID_PAYLOAD', message: 'missing field: ' + k } }];
  }
}
const esc = (v) => String(v).replace(/'/g, "''");
const report_md = String(body.report_md);
const content_hash = crypto.createHash('sha256').update(report_md).digest('hex');
return [{ json: {
  ok: true,
  mission_key: String(body.mission_key),
  repo_key: String(body.repo_key),
  agent_id: String(body.agent_id),
  branch: String(body.branch),
  head_sha: String(body.head_sha),
  report_md,
  report_md_sql: "'" + esc(report_md) + "'",
  content_hash
} }];

